// 时空回溯系统 - GitHub CDN 云端零缓存实时热更新加载器 (sisjzknxhnsnejxn-cmyk/Time-Back)
(() => {
  const BTN_NAME = '↺ 时空回溯';
  let toggleFn = null;
  let pendingOpen = false;
  let loadFailed = false;

  window.__TIMELOOP_REGISTER_TOGGLE__ = (fn) => {
    toggleFn = fn;
    if (pendingOpen) {
      pendingOpen = false;
      fn(true);
    }
  };

  try {
    replaceScriptButtons([{ name: BTN_NAME, visible: true }]);
  } catch (_) {}

  try {
    eventOn(getButtonEvent(BTN_NAME), () => {
      if (toggleFn) {
        toggleFn();
      } else if (loadFailed) {
        if (typeof toastr !== 'undefined') {
          toastr.error('时空回溯云端脚本加载失败，请检查网络或切换使用本地版 JSON');
        }
      } else {
        pendingOpen = true;
        if (typeof toastr !== 'undefined') {
          toastr.info('正在从云端加载时空回溯系统，请稍候...', '', { timeOut: 2000 });
        }
      }
    });
  } catch (_) {}

  (async () => {
    const repo = 'sisjzknxhnsnejxn-cmyk/Time-Back';
    const file = 'dist/' + encodeURIComponent('时空回溯系统') + '/index.js';
    const refs = [];

    try {
      const ctrl = new AbortController();
      const timer = setTimeout(() => ctrl.abort(), 1500);
      const res = await fetch(`https://api.github.com/repos/${repo}/commits/main`, {
        cache: 'no-store',
        signal: ctrl.signal,
      });
      clearTimeout(timer);
      if (res.ok) {
        const data = await res.json();
        if (data && typeof data.sha === 'string' && data.sha.length >= 7) {
          refs.push(data.sha.slice(0, 7));
        }
      }
    } catch (_) {}

    if (!refs.includes('0d906d4')) {
      refs.push('0d906d4');
    }
    if (!refs.includes('main')) {
      refs.push('main');
    }

    const hosts = [
      'https://testingcf.jsdelivr.net',
      'https://cdn.jsdelivr.net',
      'https://fastly.jsdelivr.net',
    ];

    for (const ref of refs) {
      for (const host of hosts) {
        try {
          await import(`${host}/gh/${repo}@${ref}/${file}`);
          return;
        } catch (_) {}
      }
    }

    loadFailed = true;
    console.error('[TimeLoop] 云端脚本所有 CDN 节点均加载失败');
    if (pendingOpen && typeof toastr !== 'undefined') {
      toastr.error('时空回溯云端脚本加载失败，请检查网络连接或使用本地版 JSON');
    }
  })();
})();
